{"function": "() => {
  const input = document.querySelector('input[type="text"]');
  if (!input) return 'no input';
  const attrs = {};
  for (const a of input.attributes) attrs[a.name] = a.value;
  return {
    value: input.value,
    validity: { valid: input.validity?.valid, valueMissing: input.validity?.valueMissing, patternMismatch: input.validity?.patternMismatch, tooLong: input.validity?.tooLong, typeMismatch: input.validity?.typeMismatch },
    validationMessage: input.validationMessage,
    attrs: attrs,
    outerHTML: input.outerHTML.slice(0, 500)
  };
}"}

{"function": "() => {
  // Look for any form, data attributes, JSON, schema, or nearby text describing expected format
  const form = document.querySelector('form');
  const labels = Array.from(document.querySelectorAll('label, .field-label, [class*="label"]')).map(e => e.outerHTML.slice(0, 300));
  const allText = document.body.innerText;
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent.slice(0, 800));
  return {
    formHTML: form ? form.outerHTML.slice(0, 1500) : 'no form',
    labels: labels,
    bodyText: allText,
    scripts: scripts,
  };
}"}

